public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Create a new bipartite graph with the same number of vertices as the target graph
    Graph<V,E> bipartiteGraph = new Graph<>(target.getNumVertices());

    // Add vertices to the bipartite graph
    for (V vertex : target.getVertices()) {
        bipartiteGraph.addVertex(vertex);
    }

    // Add edges to the bipartite graph
    for (E edge : target.getEdges()) {
        V source = edge.getSource();
        V target = edge.getTarget();
        bipartiteGraph.addEdge(source, target);
    }

    // Add the bipartite graph to the result map
    resultMap.put("bipartiteGraph", bipartiteGraph);
}

