public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
            } else if (nextChar == 't') {
                sb.append('\t');
            } else if (nextChar == 'r') {
                sb.append('\r');
            } else if (nextChar == 'f') {
                sb.append('\f');
            } else if (nextChar == 'b') {
                sb.append('\b');
            } else if (nextChar == '\\') {
                sb.append('\\');
            } else if (nextChar == '\'') {
                sb.append('\'');
            } else if (nextChar == '\"') {
                sb.append('\"');
            } else if (nextChar == 'u') {
                String hexCode = str.substring(i + 2, i + 6);
                sb.append((char) Integer.parseInt(hexCode, 16));
                i += 4;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

