public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    if (charBuffer == null || charBuffer.length < 2) {
        throw new IllegalArgumentException("Invalid char buffer: " + charBuffer);
    }
    int utfLength = classFileBuffer[constantPoolEntryIndex];
    if (utfLength < 0 || utfLength > charBuffer.length) {
        throw new IllegalArgumentException("Invalid UTF length: " + utfLength);
    }
    for (int i = 0; i < utfLength; i++) {
        charBuffer[i] = (char) classFileBuffer[constantPoolEntryIndex + i + 1];
    }
    return new String(charBuffer, 0, utfLength);
}
