    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (E edge : graph.getEdges()) {
      List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
      for (Pair<Integer, Integer> neighbor : graph.getNeighbors(edge.getSource())) {
        if (neighbor.getFirst() != edge.getTarget()) {
          separatorList.add(new Pair<>(neighbor.getFirst(), neighbor.getSecond()));
        }
      }
      for (Pair<Integer, Integer> neighbor : graph.getNeighbors(edge.getTarget())) {
        if (neighbor.getFirst() != edge.getSource()) {
          separatorList.add(new Pair<>(neighbor.getFirst(), neighbor.getSecond()));
        }
      }
      globalSeparatorList.add(new Pair<>(separatorList, edge));
    }

    return globalSeparatorList;
  }

