public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue must be non-negative");
    }
    if (intValue > 0x7fffffff) {
        throw new IllegalArgumentException("intValue must be less than or equal to 0x7fffffff");
    }
    if (intValue == 0) {
        return this;
    }
    int numBytes = 1;
    int value = intValue;
    while ((value & 0xffffff80) != 0) {
        numBytes++;
        value >>>= 7;
    }
    ensureCapacity(numBytes);
    int index = size;
    while (numBytes > 0) {
        byte b = (byte) (value & 0x7f);
        value >>>= 7;
        if (numBytes > 1) {
            b |= 0x80;
        }
        bytes[index++] = b;
        numBytes--;
    }
    size += numBytes;
    return this;
}

